const orig = $('When Called').first().json;
const impact = (orig.impact || '').trim();
const REAL_TIERS = ['Niski','Średni','Wysoki','Krytycznie ważne'];
const override = (orig.model_override != null && String(orig.model_override).trim() !== '') ? String(orig.model_override).trim() : null;
const is_image = (orig.requested_modality_of_output === 'image');

let row = null;
try { const r = $input.first().json; if (r && r.litellm_model) row = r; } catch (e) {}

let routing_default_used = false;
let routing_row_missing = false;
if (override) {
  row = { litellm_model: override, temperature: null, max_tokens: 4000, nudge: null, price_in_usd_per_1k: 0, price_out_usd_per_1k: 0, fallback_price_per_unit: null, resolution: null, impact: '__override__' };
} else if (!row) {
  row = { litellm_model: 'haxe-sonnet-4-6-direct', temperature: 0.7, max_tokens: 4000, nudge: null,
          price_in_usd_per_1k: 0.003, price_out_usd_per_1k: 0.015, fallback_price_per_unit: null, resolution: null, impact: '__fallback__' };
  if (REAL_TIERS.includes(impact)) routing_default_used = true;
  routing_row_missing = true;
} else if (row.impact === '__default__' && REAL_TIERS.includes(impact)) {
  routing_default_used = true;
}

const nudge = row.nudge ? (row.nudge + '\n\n---\n\n') : '';
const prompt = nudge + (orig.prompt || '');
const temperature = (row.temperature != null && row.temperature !== '') ? Number(row.temperature) : null;

// Multimodal (ADR-036 Block 5): content is ALWAYS an array. Image refs (ClickUp URLs from read-input)
// become image_url parts; LiteLLM fetches them. Text path only.
let imgs = [];
try { imgs = JSON.parse(orig.image_blocks_json || '[]'); } catch (e) { imgs = []; }
if (!Array.isArray(imgs)) imgs = [];
const content = [{ type: 'text', text: prompt }].concat(
  imgs.filter(b => b && b.ref).map(b => ({ type: 'image_url', image_url: { url: b.ref } }))
);
const messages = [{ role: 'user', content }];
const brak = imgs.length > 0 ? '\n\n[BRAK: obraz nieczytelny na bieżącym providerze]' : '';
const messages_text_only = [{ role: 'user', content: [{ type: 'text', text: prompt + brak }] }];

// ── Image output (Block 9) ───────────────────────────────────────────────────────────────────
// size precedence: user requested_size > model-emitted aspect > tier default. Base 1024 is safe across
// providers (gpt-image-2 + gemini 1K); 'max' maps to gpt-image-2 QUALITY, not size (avoids 1536² rejects).
function aspectToSize(aspect, base) {
  if (!aspect) return base + 'x' + base;
  const p = String(aspect).split(':');
  if (p.length !== 2) return base + 'x' + base;
  const w = Number(p[0]), h = Number(p[1]);
  if (!w || !h) return base + 'x' + base;
  if (w >= h) return base + 'x' + Math.round(base * h / w);
  return Math.round(base * w / h) + 'x' + base;
}
function parseWH(s){ const p=String(s||'').toLowerCase().split('x'); const w=Number(p[0]),h=Number(p[1]); return (w&&h)?{w:w,h:h}:null; }
// gpt-image-2 accepts arbitrary WxH within real constraints (OpenAI API): edges divisible by 16,
// aspect ratio 1:3..3:1, longest edge <= 3840, pixel count 655360..8294400. Validate, and snap to the
// nearest VALID size only on an actual violation (NOT to a fixed enum — that was a false generalization).
function gptValid(wh){ if(!wh) return false; const w=wh.w, h=wh.h; if (w%16!==0||h%16!==0) return false; const r=w/h; if (r>3||r<1/3) return false; if (Math.max(w,h)>3840) return false; const px=w*h; if (px<655360||px>8294400) return false; return true; }
function snapGptValid(wh, fallback){ if(!wh) return fallback; let w=wh.w, h=wh.h; const r=w/h; if (r>3) h=w/3; else if (r<1/3) w=h/3; const mx=Math.max(w,h); if (mx>3840){ const s=3840/mx; w*=s; h*=s; } let px=w*h; if (px<655360){ const k=Math.sqrt(655360/px)*1.02; w*=k; h*=k; } px=w*h; if (px>8294400){ const k=Math.sqrt(8294400/px); w*=k; h*=k; } const r16=x=>Math.max(16, Math.round(x/16)*16); return r16(w)+'x'+r16(h); }
const resolution = row.resolution || 'high';
const base = 1024;
const reqSize = (orig.requested_size != null && String(orig.requested_size).trim() !== '') ? String(orig.requested_size).trim() : null;
const size_overridden = !!reqSize;
const size_requested = reqSize || ((orig.aspect != null && String(orig.aspect).trim() !== '') ? aspectToSize(String(orig.aspect).trim(), base) : (base + 'x' + base));
let size = size_requested;
let resolution_note = '';

let image_model = row.litellm_model;
let img_floor = (row.fallback_price_per_unit != null) ? Number(row.fallback_price_per_unit) : null;
let img_pin = Number(row.price_in_usd_per_1k || 0);
let img_pout = Number(row.price_out_usd_per_1k || 0);
// DB-down / non-image fallback row -> never route an image to a text model; use the safe floor image model.
if (is_image && String(image_model).indexOf('image') < 0) {
  image_model = 'vertex_ai/gemini-2.5-flash-image';
  img_floor = 0.038703; img_pin = 0.0003; img_pout = 0.030;
  routing_row_missing = true;
}
if (is_image) {
  let isGpt = String(image_model).indexOf('openai/') === 0;
  const reqWH = parseWH(size_requested);
  // Block 13c: ANY shape intent — an explicit `size` OR a non-1:1 `aspect` — on a non-gpt (Gemini) tier.
  // Gemini honors neither size nor aspect through the gateway, so UPGRADE to gpt-image-2 (the only model
  // that does) and tell the user why. Quality still follows the tier (image_quality below) so it stays cheap.
  const wantsShape = !!reqSize || (reqWH && reqWH.w !== reqWH.h);
  if (wantsShape && !isGpt) {
    image_model = 'openai/gpt-image-2';
    img_floor = 0.210805; img_pin = 0.0003; img_pout = 0.030;
    isGpt = true;
    resolution_note = reqSize
      ? ('Aby zachować żądaną rozdzielczość ' + size_requested + ', użyto modelu OpenAI gpt-image-2 zamiast domyślnego modelu Gemini dla tego priorytetu (modele Gemini nie honorują wymuszonej rozdzielczości ani proporcji przez bramę LiteLLM).')
      : ('Aby zachować żądane proporcje obrazu (' + String(orig.aspect||'').trim() + '), użyto modelu OpenAI gpt-image-2 zamiast domyślnego modelu Gemini dla tego priorytetu (modele Gemini nie honorują wymuszonych proporcji przez bramę LiteLLM).');
  }
  if (isGpt) {
    // gpt-image-2 IS the resolution-flexible model (LiteLLM forwards `size` to OpenAI). Honor a valid
    // explicit request exactly; snap aspect-derived OR out-of-constraint sizes to nearest valid.
    if (reqSize && gptValid(reqWH)) {
      size = size_requested;
    } else {
      size = snapGptValid(reqWH, '1024x1024');
      if (reqSize && size !== size_requested) {
        const snapMsg = 'Żądana rozdzielczość ' + size_requested + ' nie jest w pełni obsługiwana; wygenerowano w najbliższej zgodnej: ' + size + '.';
        resolution_note = resolution_note ? (resolution_note + ' ' + snapMsg) : snapMsg;
      }
    }
  }
  // Gemini tier with NO explicit size: LiteLLM drops gemini imageConfig (returns ~1:1 1K); size is moot.
}
const size_snapped = (size !== size_requested);
// gpt-image-2 quality from tier (it only ever serves 'max' -> high, matching Block 8's measured floor).
const image_quality = (String(image_model).indexOf('openai/') === 0)
  ? (resolution === 'max' ? 'high' : (resolution === 'high' ? 'medium' : 'low'))
  : null;
const image_prompt = (orig.prompt || ''); // raw — no text deliberation nudge in an image prompt

return [{ json: {
  is_image,
  litellm_model: row.litellm_model,
  temperature,
  max_tokens: Number(row.max_tokens),
  price_in_usd_per_1k: is_image ? img_pin : Number(row.price_in_usd_per_1k || 0),
  price_out_usd_per_1k: is_image ? img_pout : Number(row.price_out_usd_per_1k || 0),
  prompt,
  messages,
  messages_text_only,
  had_images: imgs.length > 0,
  image_count: imgs.length,
  image_model,
  image_prompt,
  image_quality,
  size,
  size_requested,
  size_overridden,
  size_snapped,
  resolution_note,
  resolution,
  fallback_price_per_unit: img_floor,
  impact,
  task_type: orig.task_type || '',
  clickup_task_id: orig.clickup_task_id || '',
  triggered_by: orig.triggered_by || 'explicit_command',
  invocation_type: orig.invocation_type || 'explicit',
  caller_user_id: orig.caller_user_id || '',
  process_type: orig.process_type || '',
  routing_default_used,
  routing_row_missing
} }];

const routing = $('Resolve Routing').first().json;

// Pick whichever LLM branch produced a real completion. Order: primary -> Opus fallback (transient
// error, ADR-037, image kept) -> Retry Text-Only (Block 6: image stripped after a 4xx on the image).
let okCall = null, okFb = null, okRetry = null;
try { okCall = $('Call LiteLLM').first().json; } catch (e) {}
try { okFb = $('Fallback to Opus').first().json; } catch (e) {}
try { okRetry = $('Retry Text-Only').first().json; } catch (e) {}
const hasBody = (x) => x && x.body && x.body.choices;
let resp = {}, fell_back = false, image_unprocessable = false;
if (hasBody(okCall)) { resp = okCall; }
else if (hasBody(okFb)) { resp = okFb; fell_back = true; }
else if (hasBody(okRetry)) { resp = okRetry; image_unprocessable = true; }
else { resp = (okCall && okCall.body) ? okCall : ((okFb && okFb.body) ? okFb : (okRetry || {})); }

const body = resp.body || {};
const headers = resp.headers || {};
const usage = body.usage || {};
const input_tokens = (usage.prompt_tokens != null) ? usage.prompt_tokens : null;
const output_tokens = (usage.completion_tokens != null) ? usage.completion_tokens : null;
let completion = '';
try { completion = body.choices[0].message.content || ''; } catch (e) {}
const ch = headers['x-litellm-response-cost'];
const usd_cost = (ch != null && ch !== '') ? Number(ch) : null;

// Both the Opus fallback and the text-only retry run on opus-4-8-direct.
const onOpus = fell_back || image_unprocessable;
const fbAlias = 'haxe-opus-4-8-direct';
const alias = onOpus ? fbAlias : (routing.litellm_model || '');
const model_used = (body.model && body.model.trim()) ? body.model.trim() : alias;
const provider = alias.includes('gemini') ? 'litellm/vertex' : 'litellm/anthropic-direct';

// On any Opus path the model differs from the routed one. LiteLLM's response-cost header is
// authoritative; these price columns are only a dormant backup. Keep them roughly correct for Opus 4.8.
const price_in = onOpus ? 0.015 : routing.price_in_usd_per_1k;
const price_out = onOpus ? 0.075 : routing.price_out_usd_per_1k;

return [{ json: {
  completion,
  model_used,
  provider,
  input_tokens, output_tokens, usd_cost,
  price_in_usd_per_1k: price_in,
  price_out_usd_per_1k: price_out,
  routing_default_used: !!routing.routing_default_used,
  routing_row_missing: !!routing.routing_row_missing,
  fell_back_to_opus: fell_back,
  image_unprocessable,
  images_dropped: image_unprocessable ? (routing.image_count || 0) : 0,
  impact: routing.impact,
  task_type: routing.task_type,
  clickup_task_id: routing.clickup_task_id,
  triggered_by: routing.triggered_by,
  invocation_type: routing.invocation_type,
  caller_user_id: routing.caller_user_id,
  process_type: routing.process_type
} }];

// Block 9: normalise one image-generation attempt. Success is gated on the PAYLOAD (data[0].b64_json),
// not HTTP status (the Docling gotcha). Reads the primary call, then the single fallback hop.
const routing = $('Resolve Routing').first().json;
let ok = null, fb = null;
try { ok = $('Call Image Gen').first().json; } catch (e) {}
try { fb = $('Fallback Image Gen').first().json; } catch (e) {}

const getImg = (x) => {
  try { return (x && x.body && x.body.data && x.body.data[0] && x.body.data[0].b64_json) ? x : null; }
  catch (e) { return null; }
};

let resp = null, degraded = false, model_used = routing.image_model;
if (getImg(ok)) { resp = ok; }
else if (getImg(fb)) { resp = fb; degraded = true; model_used = 'vertex_ai/gemini-2.5-flash-image'; }
const succeeded = !!resp;

let b64 = null, mime = 'image/png', header_cost = null, itok = 0, otok = null;
if (resp) {
  const body = resp.body || {};
  const headers = resp.headers || {};
  try { b64 = body.data[0].b64_json || null; } catch (e) {}
  const usage = body.usage || {};
  const out = (usage.output_tokens != null) ? usage.output_tokens
            : ((usage.completion_tokens != null) ? usage.completion_tokens
            : ((usage.total_tokens != null) ? usage.total_tokens : null));
  otok = (out != null) ? Number(out) : null;
  const inp = (usage.input_tokens != null) ? usage.input_tokens
            : ((usage.prompt_tokens != null) ? usage.prompt_tokens : 0);
  itok = (inp != null) ? Number(inp) : 0;
  const ch = headers['x-litellm-response-cost'];
  header_cost = (ch != null && ch !== '') ? Number(ch) : null;
}

return [{ json: {
  is_image_result: true,
  succeeded,
  b64_json: b64,
  mime,
  model_used,
  header_cost,
  input_tokens: itok,
  output_tokens: otok,
  image_degraded: degraded,
  size: routing.size,
  size_overridden: !!routing.size_overridden,
  resolution_note: routing.resolution_note || '',
  floor: (routing.fallback_price_per_unit != null) ? Number(routing.fallback_price_per_unit) : null,
  price_in_usd_per_1k: routing.price_in_usd_per_1k,
  price_out_usd_per_1k: routing.price_out_usd_per_1k,
  impact: routing.impact,
  task_type: routing.task_type,
  clickup_task_id: routing.clickup_task_id,
  caller_user_id: routing.caller_user_id,
  process_type: routing.process_type,
  invocation_type: routing.invocation_type
} }];

// Block 9: single convergence point for the text and image branches. Reads whichever Parse node ran
// (try/catch absolute refs) and emits ONE uniform schema for Log Model Run + the degradation chain +
// Shape Output. Keeps Shape Output the sole branch-free leaf (sub-workflow return determinism).
let img = null, txt = null;
try { img = $('Parse Image').first().json; } catch (e) {}
try { txt = $('Parse Response').first().json; } catch (e) {}
const isImg = !!(img && img.is_image_result);
let rrm = false;
try { rrm = !!$('Resolve Routing').first().json.routing_row_missing; } catch (e) {}

if (isImg) {
  // Cost layering: live header (>0) -> token-math (filled price_out) -> per-image floor. A header miss
  // sets cost_header_missing regardless of which layer prices it (drives the WARN).
  const header = (img.header_cost != null && Number(img.header_cost) > 0) ? Number(img.header_cost) : null;
  let usd_cost = null, cost_header_missing = false;
  let input_tokens = img.input_tokens, output_tokens = img.output_tokens;
  if (header != null) {
    usd_cost = header;
  } else {
    cost_header_missing = true;
    if (img.output_tokens != null) {
      usd_cost = null; // Log Model Run prices by token-math (input_tokens default 0 + filled price_out)
    } else {
      usd_cost = (img.floor != null) ? img.floor : null; // per-image floor, last resort
      input_tokens = null; output_tokens = null;
    }
  }
  const provider = (String(img.model_used || '').indexOf('openai') >= 0) ? 'litellm/openai' : 'litellm/vertex';
  return [{ json: {
    output_modality: 'image',
    success: !!img.succeeded,
    completion: '',
    b64_json: img.b64_json || null,
    mime: img.mime || 'image/png',
    size: img.size || null,
    size_overridden: !!img.size_overridden,
    resolution_note: img.resolution_note || '',
    image_degraded: !!img.image_degraded,
    cost_header_missing,
    model_used: img.model_used,
    provider,
    input_tokens, output_tokens, usd_cost,
    price_in_usd_per_1k: img.price_in_usd_per_1k,
    price_out_usd_per_1k: img.price_out_usd_per_1k,
    impact: img.impact,
    task_type: img.task_type || '',
    clickup_task_id: img.clickup_task_id || '',
    triggered_by: 'image_gen',
    invocation_type: img.invocation_type || 'explicit',
    caller_user_id: img.caller_user_id || '',
    process_type: img.process_type || '',
    routing_default_used: false,
    routing_row_missing: rrm,
    fell_back_to_opus: false,
    image_unprocessable: false,
    images_dropped: 0
  } }];
}

const t = txt || {};
return [{ json: {
  output_modality: 'text',
  success: true,
  completion: t.completion || '',
  b64_json: null,
  mime: null,
  size: null,
  size_overridden: false,
  image_degraded: false,
  cost_header_missing: false,
  model_used: t.model_used,
  provider: t.provider,
  input_tokens: (t.input_tokens != null) ? t.input_tokens : null,
  output_tokens: (t.output_tokens != null) ? t.output_tokens : null,
  usd_cost: (t.usd_cost != null) ? t.usd_cost : null,
  price_in_usd_per_1k: t.price_in_usd_per_1k,
  price_out_usd_per_1k: t.price_out_usd_per_1k,
  impact: t.impact,
  task_type: t.task_type || '',
  clickup_task_id: t.clickup_task_id || '',
  triggered_by: t.triggered_by || 'explicit_command',
  invocation_type: t.invocation_type || 'explicit',
  caller_user_id: t.caller_user_id || '',
  process_type: t.process_type || '',
  routing_default_used: !!t.routing_default_used,
  routing_row_missing: !!t.routing_row_missing,
  fell_back_to_opus: !!t.fell_back_to_opus,
  image_unprocessable: !!t.image_unprocessable,
  images_dropped: t.images_dropped || 0
} }];
